"""Exact-model setting frames generated by each appliance's vendor codec."""

# BLE state and catalog mappings contain heterogeneous protocol values.
# ruff: file-ignore[any-type, pytest-raises-too-broad, import-outside-top-level]
from typing import Any

import pytest

from custom_components.midea_ac_lan.ble.appliances import HEATER, HOOD, setting


@pytest.mark.parametrize(
    ("profile", "key", "value", "wire"),
    [
        (HOOD, "light", True, "aa12b6000000000000021101020201ffffff22"),
        (HOOD, "light", False, "aa12b6000000000000021101020200ffffff23"),
        (
            HEATER,
            "beep",
            True,
            "aa1ee3000000000000021415010000000000000000000000000000000001d2",
        ),
        (
            HEATER,
            "beep",
            False,
            "aa1ee3000000000000021415000000000000000000000000000000000000d4",
        ),
    ],
)
def test_setting(profile: Any, key: Any, value: Any, wire: Any) -> None:
    """Verify setting."""
    assert setting(profile, key, value) == bytes.fromhex(wire)


@pytest.mark.parametrize("profile", [HOOD, HEATER])
def test_power_is_not_a_ble_setting(profile: Any) -> None:
    """Verify power is not a ble setting."""
    with pytest.raises(ValueError, match="Unsupported"):
        setting(profile, "power", True)


def test_dishwasher_only_encodes_isolated_settings() -> None:
    """Verify dishwasher only encodes isolated settings."""
    from custom_components.midea_ac_lan.ble.appliances import DISH

    assert DISH.query.hex() == "aa0be1000000000000030011"
    for value in (True, False):
        frame = setting(DISH, "beep", value)
        assert frame[9:12] == bytes.fromhex("029005")
        assert frame[16] == int(value)
        assert len(frame) == 49
        assert sum(frame[1:]) % 256 == 0
        lock = setting(DISH, "child_lock", value)
        assert lock[10:12] == bytes((0x83, 3 if value else 4))
    for key in ("start", "program", "power", "operator", "raw"):
        with pytest.raises(ValueError):
            setting(DISH, key, True)


def test_purifier_status_and_single_setting() -> None:
    """Verify purifier status and single setting."""
    from custom_components.midea_ac_lan.ble.appliances import PURIFIER, parse
    from custom_components.midea_ac_lan.ble.controls import command
    from custom_components.midea_ac_lan.ble.protocol import signed

    body = bytes.fromhex("ff0103004008800003105063560000001340c4000a00071218")
    raw = b"\xaa" + signed(bytes([10 + len(body), 0xED, 0, 0, 0, 0, 0, 0, 3]) + body)
    state = parse(PURIFIER, raw)
    assert (state["in_tds"], state["out_tds"], state["inlet"]) == (196, 10, 24)
    assert (state["ro_life"], state["pcb_life"]) == (99, 86)
    assert state["controls"]["power"] == "on"
    assert "antifreeze" not in state["controls"]
    assert command(PURIFIER, "sleep", "off", {})[10:-1].hex() == "1501010401000000"
    with pytest.raises(ValueError):
        parse(PURIFIER, raw[:-1])


def test_appliance_status_formats_and_idle_guards() -> None:
    """Verify appliance status formats and idle guards."""
    from custom_components.midea_ac_lan.ble import dishwasher, purifier
    from custom_components.midea_ac_lan.ble.appliances import (
        DISH,
        idle,
        parse,
    )
    from custom_components.midea_ac_lan.ble.protocol import signed

    def report(kind: Any, body: Any, version: Any = 0) -> Any:
        """Apply report."""
        return b"\xaa" + signed(
            bytes([len(body) + 10, kind, 0, 0, 0, 0, 0, version, 3]) + body,
        )

    dish = report(DISH.kind, bytes(39))
    assert parse(DISH, dish)["status"] == 0
    assert idle(DISH, parse(DISH, dish))
    assert not idle(DISH, {"status": 3, "operator": True})
    with pytest.raises(ValueError):
        dishwasher.parse_status(dish[:-1])
    with pytest.raises(ValueError):
        dishwasher.setting_frame("beep", "on")  # type: ignore[arg-type]
    heater_body = bytearray(30)
    heater_body[:2] = b"\x01\x01"
    heater_body[6] = 42
    assert parse(HEATER, report(HEATER.kind, heater_body))["temperature"] == 42
    assert idle(HEATER, {"power": False, "burning": False})
    assert not idle(HEATER, {"power": False, "burning": True})
    hood = report(HOOD.kind, b"\x11\x09\x01\x00\x01\x07" + bytes(7), 2)
    assert parse(HOOD, hood) == {"power": False, "gear": 0, "light": False}
    assert idle(HOOD, parse(HOOD, hood))
    assert not idle(HOOD, {"power": False, "gear": 1})
    for body in [
        b"\x11\x01\xff",
        b"\x11\x02\x01\x00",
        b"\x11\x01\x07" + bytes([255]) * 7,
    ]:
        with pytest.raises(ValueError, match="Unsupported"):
            parse(HOOD, report(HOOD.kind, body, 2))
    with pytest.raises(ValueError, match="Unsupported"):
        parse(HEATER, report(HEATER.kind, bytes(30)))
    with pytest.raises(ValueError, match="switch value"):
        setting(HOOD, "light", 1)
    for body in [
        b"",
        b"\xff\x01\x03\x00",
        b"\xff\x01\x03\x00\x40\x00",
        b"\xff\x01\x03\x13\x10\x00",
        b"\xff\x01\x03\x00\x10\x00",
        b"\xff\x01\x03\xfe\x1f\x00",
    ]:
        with pytest.raises(ValueError):
            purifier.parse_body(body)
    full = b"\xff\x01\x03\x00\x40" + bytes(4) + b"\x3c\x30" + bytes(3)
    assert purifier.parse_body(full)["controls"]["antifreeze"] == "off"


def test_heater_extended_telemetry_and_errors() -> None:
    """Verify 5111102Z heater telemetry, work status, and fault codes."""
    from custom_components.midea_ac_lan.ble.appliances import HEATER_ERRORS, parse
    from custom_components.midea_ac_lan.ble.protocol import signed

    def make_heater_frame(body: bytearray) -> bytes:
        return b"\xaa" + signed(
            bytes([len(body) + 10, HEATER.kind, 0, 0, 0, 0, 0, 0, 3]) + body,
        )

    body = bytearray(42)
    body[:2] = b"\x01\x01"
    body[2] = 0x03  # power + burning
    body[5] = 43  # outlet
    body[6] = 42  # target temperature
    body[7] = 52  # water_volume -> 5.2 L/min
    body[14] = 35  # return_water
    body[15] = 0x14  # rated_litre default 16
    body[18] = 8  # gas lift -> 50%
    body[20] = 0x02  # change_litre_switch on
    body[26] = 22  # inlet
    body[34] = 30  # cold_conservation_duration -> 3.0 min
    body[40] = 0x08  # new_filter_problem=True, cruise_antifreeze=True, error=False
    state = parse(HEATER, make_heater_frame(body))
    assert state["work_status"] == "加热中"
    assert state["inlet"] == 22
    assert state["return_water"] == 35
    assert state["water_flow"] == 5.2
    assert state["gas_lift_percent"] == 50
    assert state["change_litre"] == 8
    assert state["cold_conservation_duration"] == 3.0
    assert state["error_code"] == "无故障"
    assert state["new_filter_problem"] is True
    assert state["cruise_antifreeze"] is True
    assert state["cruise_antifreeze_error"] is False

    # Zero-cold heating & holding & standby & powered off
    body[21] = 0x02  # zero_single
    assert parse(HEATER, make_heater_frame(body))["work_status"] == "零冷水·加热中"
    body[2] = 0x01  # power on, not burning
    assert parse(HEATER, make_heater_frame(body))["work_status"] == "零冷水·保温中"
    body[21] = 0x00
    assert parse(HEATER, make_heater_frame(body))["work_status"] == "待机中"
    assert parse(HEATER, make_heater_frame(body))["change_litre"] == 16
    body[2] = 0x00
    assert parse(HEATER, make_heater_frame(body))["work_status"] == "已关机"

    # All 23 fault codes
    for raw_index, bit, expected in HEATER_ERRORS:
        err_body = bytearray(42)
        err_body[:2] = b"\x01\x01"
        err_body[raw_index - 10] = 1 << bit
        err_state = parse(HEATER, make_heater_frame(err_body))
        assert err_state["error_code"] == expected
        assert err_state["work_status"] == "有故障"
